  document.getElementById('theme-toggle').addEventListener('click',()=>{document.body.classList.toggle('dark');localStorage.setItem('sisp_dark',document.body.classList.contains('dark')?'1':'0')});
  if(localStorage.getItem('sisp_dark')==='1')document.body.classList.add('dark');
